const db = client.db("shop");
const products = db.collection("products");

// Insert one
await products.insertOne({ name: "Laptop", price: 999, inStock: true });

// Insert many
await products.insertMany([
  { name: "Mouse", price: 25 },
  { name: "Keyboard", price: 75 }
]);

// Find all in-stock products
const cursor = products.find({ inStock: true });
const items = await cursor.toArray();

// Projection: only return name and price
const names = await products.find({}, { projection: { name: 1, price: 1, _id: 0 } }).toArray();
